parameters.jsCode:
// S6 (ENG-20260928-020): the historical smoke-test manifest ID is no longer hard-coded.
// A manual run of this TEST path now fails closed at node 00 (missing ID).
return [
  {
    json: {
      production_readiness_manifest_id:
        ""
    }
  }
];

// AGENT-007 — NODE 00 (S6, ENG-20260928-020)
// R-012: the caller-supplied production_readiness_manifest_id is authoritative.
//        No manifest ID is hard-coded (the historical smoke-test ID c0012923 was removed).
// R-013: caller-supplied status / readiness_state / readiness_manifest_json /
//        paid_generation_authorisation are IGNORED. Authorisation comes only from the
//        persisted Supabase readiness manifest read in node 01C.
const input = $input.first().json;

const requestedId =
  String(input.production_readiness_manifest_id ?? '').trim();

if (!requestedId) {
  throw new Error(
    'AGENT-007 BLOCKED (MISSING_PRODUCTION_READINESS_MANIFEST_ID): AGENT-007 requires production_readiness_manifest_id. No reads or writes performed.'
  );
}

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!UUID_PATTERN.test(requestedId)) {
  throw new Error(
    'AGENT-007 BLOCKED (MALFORMED_PRODUCTION_READINESS_MANIFEST_ID): production_readiness_manifest_id must be a UUID. No reads or writes performed.'
  );
}

const ignoredCallerFields = [
  'status',
  'readiness_state',
  'readiness_manifest_json',
  'paid_generation_authorisation',
  'paid_generation_authorized',
  'paid_generation_authorised'
].filter(field => input[field] !== undefined);

return [
  {
    json: {
      production_readiness_manifest_id:
        requestedId.toLowerCase(),

      is_mock_input:
        false,

      ignored_caller_supplied_fields:
        ignoredCallerFields,

      agent_version:
        "agent007-asset-creation-canonicalization-producer-v0.1",

      prompt_version:
        "agent007-asset-creation-v0.1"
    }
  }
];

const input = $input.first().json;

return [
  {
    json: {
      agent: "AGENT-007",

      status: "STOPPED",

      stop_reason: "ASSET_CREATION_NOT_AUTHORIZED",

      production_readiness_manifest_id:
        input.production_readiness_manifest_id ?? null,

      manifest_source:
        input.manifest_source ?? null,

      received_status:
        input.status ?? null,

      received_readiness_state:
        input.readiness_state ?? null,

      message:
        "AGENT-007 stopped because the production readiness manifest is not authorized for asset creation.",

      required_state: {
        status: "APPROVED",
        readiness_state: "NEEDS_ASSET_CREATION"
      },

      next_action:
        "Human review or AGENT-006 state correction is required before AGENT-007 may create assets."
    }
  }
];

const input = $input.first().json;

const manifest = input.readiness_manifest_json;

if (!manifest || typeof manifest !== "object") {
  throw new Error(
    "AGENT-007 cannot prepare context because readiness_manifest_json is missing."
  );
}

const queue = Array.isArray(manifest.asset_creation_queue)
  ? manifest.asset_creation_queue
  : [];

if (queue.length === 0) {
  throw new Error(
    "AGENT-007 was authorized for asset creation, but asset_creation_queue is empty."
  );
}

const episode = manifest.episode ?? {};

const assetCreationBatchId = `A007-${Date.now()}`;

return [
  {
    json: {
      asset_creation_batch_id:
        assetCreationBatchId,

      production_readiness_manifest_id:
        input.production_readiness_manifest_id,

      asset_resolution_run_id:
        manifest.asset_resolution_run_id ?? null,

      source_production_manifest_id:
        manifest.source_production_manifest_id ?? null,

      production_plan_run_id:
        manifest.source_production_plan_run_id ?? null,

      episode_script_id:
        episode.episode_script_id ?? null,

      episode_code:
        episode.episode_code ?? null,

      script_version:
        episode.script_version ?? null,

      title_working:
        episode.title_working ?? null,

      job_count:
        queue.length,

      asset_creation_queue:
        queue,

      manifest_source:
        input.manifest_source,

      agent_version:
        input.agent_version,

      prompt_version:
        input.prompt_version,

      batch_status:
        "IN_PROGRESS",

      human_approval_required:
        true
    }
  }
];

// AGENT-007 — Build Current Asset Creation Brief
// Reusable across episodes and asset creation attempts.
//
// Attempt numbers are supplied by Node 05A.
// This node must never hard-code an episode-specific retry.

const job = $json;

const brief = job.creation_brief ?? {};

const requirementType =
  job.requirement_type ??
  brief.asset_type ??
  null;

const supportedTypes = [
  "PROP",
  "OVERLAY_VFX"
];

const supported =
  supportedTypes.includes(requirementType);


// ----------------------------------------------------
// SOURCE CONSTRAINTS
// ----------------------------------------------------

const rawConstraints =
  Array.isArray(brief.constraints)
    ? brief.constraints
    : [];


// Remove governance and database instructions that
// should not be sent to the image-generation provider.
//
// AGENT-007 registers REVIEW candidates only.
// Human canonical approval happens separately.

const providerConstraints =
  rawConstraints.filter(constraint => {

    const text =
      String(constraint ?? "")
        .toLowerCase()
        .trim();

    if (!text) {
      return false;
    }

    // Remove instructions telling the provider
    // to approve or lock generated assets.

    if (
      text.includes("register the finished asset") &&
      (
        text.includes("approved") ||
        text.includes("locked")
      )
    ) {
      return false;
    }

    // Remove database and registry alias instructions.

    if (
      text.includes("registry aliases") ||
      (
        text.includes("aliases field") &&
        text.includes("agent-006")
      )
    ) {
      return false;
    }

    return true;
  });


// ----------------------------------------------------
// ASSET NAME NORMALIZATION
// ----------------------------------------------------

const temporaryAssetId =
  brief.temporary_asset_id ??
  job.source_asset_id ??
  null;

const sourceLabels =
  Array.isArray(brief.source_labels)
    ? brief.source_labels
    : [];


// Detect generic workflow labels that should not
// become the human-readable asset name.

function isGenericLabel(value) {

  if (!value || typeof value !== "string") {
    return true;
  }

  const text = value.trim();

  if (!text) {
    return true;
  }

  if (/^TMP_/i.test(text)) {
    return true;
  }

  if (
    /^Agent-\d+\s+approved\s+(new|reused)\s+asset$/i.test(text)
  ) {
    return true;
  }

  return false;
}


// Convert a temporary asset ID into a readable name.
//
// Example:
// TMP_EP005_BERRY_SMUDGE_OVERLAYS
// becomes:
// Berry smudge overlays

function humanizeAssetId(value) {

  if (!value) {
    return null;
  }

  let text = String(value)
    .replace(/^TMP_/i, "")
    .replace(/^EP\d+_/i, "")
    .replace(/_/g, " ")
    .trim()
    .toLowerCase();

  if (!text) {
    return null;
  }

  return (
    text.charAt(0).toUpperCase() +
    text.slice(1)
  );
}


// Normalize words for comparing possible names.

function normalizeWords(value) {

  return String(value ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean);

}


const fallbackName =
  humanizeAssetId(temporaryAssetId);

const fallbackWords =
  normalizeWords(fallbackName);


// Collect meaningful candidate names.

const candidateLabels = [
  brief.requested_name,
  ...sourceLabels
]
  .filter(value => !isGenericLabel(value))
  .map(value => String(value).trim());


// Remove duplicate names.

const uniqueLabels =
  [...new Set(candidateLabels)];


// Search for an exact readable match.

const exactMatch =
  fallbackName
    ? uniqueLabels.find(
        label =>
          normalizeWords(label).join(" ") ===
          fallbackWords.join(" ")
      )
    : null;


// Allow useful descriptive additions.
//
// Example:
// Hand mirror → Tiny hand mirror
//
// Avoid contextual or count-specific words.

const unwantedExtraWords = new Set([
  "one",
  "two",
  "three",
  "four",
  "five",
  "current",
  "final",
  "selected",
  "reflected",
  "mikko",
  "lumi",
  "cheek",
  "nose",
  "mouth",
  "skin",
  "face",
  "state",
  "mask"
]);


let enhancedMatch = null;

if (fallbackWords.length > 0) {

  const exactIndex =
    exactMatch
      ? uniqueLabels.indexOf(exactMatch)
      : Infinity;

  for (let i = 0; i < uniqueLabels.length; i++) {

    if (i >= exactIndex) {
      break;
    }

    const label = uniqueLabels[i];

    const words =
      normalizeWords(label);

    const containsAllFallbackWords =
      fallbackWords.every(word =>
        words.includes(word)
      );

    if (!containsAllFallbackWords) {
      continue;
    }

    const extraWords =
      words.filter(
        word => !fallbackWords.includes(word)
      );

    const hasBadExtraWord =
      extraWords.some(word =>
        unwantedExtraWords.has(word)
      );

    if (
      extraWords.length <= 2 &&
      !hasBadExtraWord
    ) {
      enhancedMatch = label;
      break;
    }
  }
}


// ----------------------------------------------------
// FINAL HUMAN-READABLE NAME
// ----------------------------------------------------

const resolvedRequestedName =
  enhancedMatch ??
  exactMatch ??
  fallbackName ??
  uniqueLabels[0] ??
  job.source_label ??
  null;


// ----------------------------------------------------
// ATTEMPT NUMBER — AUTOMATIC
// ----------------------------------------------------
//
// Node 05A determines the correct attempt number
// using previous Supabase records.
//
// This node validates the value.
//
// Do not hard-code asset names or attempt numbers here.

const resolvedAttemptNumber =
  Number(job.attempt_number);

if (
  !Number.isInteger(resolvedAttemptNumber) ||
  resolvedAttemptNumber < 1 ||
  resolvedAttemptNumber > 3
) {
  throw new Error(
    `AGENT-007 invalid attempt number for ` +
    `${temporaryAssetId ?? "UNKNOWN"}. ` +
    `Received: ${job.attempt_number ?? "MISSING"}. ` +
    `Check Node 05A.`
  );
}


// ----------------------------------------------------
// FINAL NORMALIZED JOB
// ----------------------------------------------------

return {
  json: {
    ...job,

    normalized_asset_type:
      requirementType,

    requested_name:
      resolvedRequestedName,

    // Preserve the cleaned asset name and constraints
    // for downstream database registration.

    creation_brief: {
      ...brief,

      requested_name:
        resolvedRequestedName,

      temporary_asset_id:
        temporaryAssetId,

      source_labels:
        sourceLabels,

      constraints:
        providerConstraints,

      // Keep original constraints for traceability.
      source_constraints:
        rawConstraints
    },

    temporary_asset_id:
      temporaryAssetId,

    source_labels:
      sourceLabels,

    // Node 07A uses these provider-safe constraints
    // when constructing the Runway prompt.

    constraints:
      providerConstraints,

    provider_route_supported:
      supported,

    provider_route:
      supported
        ? "VISUAL_IMAGE_GENERATION"
        : "UNSUPPORTED_ASSET_TYPE",

    job_status:
      supported
        ? "READY_FOR_PROVIDER_ROUTING"
        : "UNSUPPORTED_ASSET_TYPE",

    // This is supplied by Node 05A.
    attempt_number:
      resolvedAttemptNumber
  }
};

const job = $json;

return {
  json: {
    ...job,

    provider: null,
    provider_job_id: null,
    output_source_url: null,
    output_storage_path: null,

    generation_prompt: null,

    generation_settings_json: {},

    generation_metadata_json: {},

    qc_status: "REVIEW_REQUIRED",

    qc_notes: [
      "Unsupported asset type encountered by AGENT-007."
    ],

    candidate_asset_id: null,

    job_status: "UNSUPPORTED_ASSET_TYPE",

    error_message:
      `Unsupported asset type: ${job.normalized_asset_type ?? "UNKNOWN"}`
  }
};

// AGENT-007 — Prepare Image Generation Request
//
// All reusable visual assets generated by this node
// should request transparent backgrounds by default.
//
// Supported current asset types:
// - PROP
// - OVERLAY_VFX
//
// This node prepares the provider-facing prompt and
// generation settings only. It does not submit the job.

const job = $json;

// ----------------------------------------------------
// NORMALIZE INPUT ARRAYS
// ----------------------------------------------------

const constraints =
  Array.isArray(job.constraints)
    ? job.constraints
    : [];

const affectedShots =
  Array.isArray(job.affected_shots)
    ? job.affected_shots
    : [];

const sourceLabels =
  Array.isArray(job.source_labels)
    ? job.source_labels
    : [];

// ----------------------------------------------------
// CORE ASSET IDENTITY
// ----------------------------------------------------

const assetType =
  job.normalized_asset_type ??
  job.requirement_type ??
  "UNKNOWN";

const requestedName =
  job.requested_name ??
  job.creation_brief?.requested_name ??
  job.source_label ??
  "Unnamed asset";

const temporaryAssetId =
  job.temporary_asset_id ??
  job.source_asset_id ??
  job.creation_brief?.temporary_asset_id ??
  "UNKNOWN";

// ----------------------------------------------------
// BACKGROUND POLICY
// ----------------------------------------------------
//
// AGENT-007 currently supports visual generation for:
// PROP
// OVERLAY_VFX
//
// Both should be reusable compositing assets.
//
// Therefore both require transparency.

const transparentAssetTypes = [
  "PROP",
  "OVERLAY_VFX"
];

const transparentBackground =
  transparentAssetTypes.includes(assetType);

const backgroundRequirement =
  transparentBackground
    ? "transparent_background_required"
    : "opaque_background";

// ----------------------------------------------------
// GENERATION PROMPT
// ----------------------------------------------------

const generationPrompt = [
  `Create one production-ready candidate asset for the Mikko & Lumi preschool project.`,
  `Asset type: ${assetType}.`,
  `Requested name: ${requestedName}.`,
  `Temporary source asset ID: ${temporaryAssetId}.`,
  `Source labels: ${sourceLabels.join(", ") || "None provided"}.`,
  `Affected shots: ${affectedShots.join(", ") || "None provided"}.`,
  `Background requirement: ${backgroundRequirement}.`,

  transparentBackground
    ? `The asset must be isolated on a genuinely transparent background with a usable alpha channel. Do not place it on white, black, grey, coloured, studio, gradient, or environmental backgrounds.`
    : `Use a clean opaque background suitable for the approved production requirement.`,

  `Constraints:`,

  ...constraints.map(
    (constraint, index) =>
      `${index + 1}. ${constraint}`
  ),

  `Do not redesign Mikko or Lumi.`,
  `Do not add text, logos, captions, labels, borders, or watermarks.`,
  `Do not generate a mockup, presentation board, product card, frame, or decorative backdrop.`,
  `Keep the asset clearly separated from the canvas edges.`,
  `Produce one clean reusable asset suitable for preschool production and downstream compositing.`
].join("\n");

// ----------------------------------------------------
// FINAL PROVIDER REQUEST
// ----------------------------------------------------

return {
  json: {
    ...job,

    provider_adapter:
      "VISUAL_IMAGE_GENERATION",

    generation_prompt:
      generationPrompt,

    generation_settings_json: {
      asset_type:
        assetType,

      background_requirement:
        backgroundRequirement,

      style_target:
        "preschool-readable, clean, reusable",

      output_count:
        1,

      transparent_background:
        transparentBackground
    },

    job_status:
      "READY_FOR_PROVIDER_EXECUTION"
  }
};

// AGENT-007 — NODE 07C
// Normalize Runway Submission Response
//
// Requires a verified, one-time dispatch claim.
// Preserves the reservation ID for the checkpoint RPC.
//
// No API requests or database writes occur here.

const inputs = $input.all();

if (inputs.length !== 1) {
  throw new Error(
    `SAFETY STOP: Expected one Runway response, received ${inputs.length}.`
  );
}

const response = inputs[0].json;


// ------------------------------------------------------------
// 01 — RECOVER MATCHING DISPATCH CONTEXT
// ------------------------------------------------------------

let request;

try {
  request =
    $('07A6 - Verify Runway Dispatch Claim')
      .itemMatching(0)
      .json;

} catch (error) {

  throw new Error(
    "SAFETY STOP: Cannot match Runway response to " +
    "its verified dispatch claim. " +
    error.message
  );

}


// ------------------------------------------------------------
// 02 — REQUIRE VERIFIED AUTHORISATION
// ------------------------------------------------------------

if (
  request.reservation_created !== true ||
  request.submission_authorized !== true ||
  request.dispatch_claimed !== true ||
  request.dispatch_claim_status !==
    "SUBMISSION_DISPATCH_CLAIMED"
) {
  throw new Error(
    "SAFETY STOP: Runway response has no verified dispatch claim."
  );
}


// ------------------------------------------------------------
// 03 — VALIDATE RESERVATION ID
// ------------------------------------------------------------

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (
  typeof request.reservation_id !== "string" ||
  !uuidPattern.test(request.reservation_id)
) {
  throw new Error(
    "SAFETY STOP: Missing or invalid reservation ID."
  );
}


// ------------------------------------------------------------
// 04 — VALIDATE ASSET IDENTITY
// ------------------------------------------------------------

if (
  !request.asset_creation_batch_id ||
  !request.production_readiness_manifest_id ||
  !request.requirement_key ||
  !request.source_asset_id ||
  !request.generation_prompt
) {
  throw new Error(
    "SAFETY STOP: Dispatch context has incomplete asset identity."
  );
}

if (Number(request.attempt_number) !== 1) {
  throw new Error(
    "SAFETY STOP: Reservation v0.1 permits attempt 1 only."
  );
}


// ------------------------------------------------------------
// 05 — BLOCK RESUMED TASKS
// ------------------------------------------------------------

if (
  request.resume_existing_provider_task === true ||
  request.resumed_provider_task === true ||
  request.resume_provider_job_id ||
  request.provider_job_id
) {
  throw new Error(
    "SAFETY STOP: Existing task entered the new-submission path."
  );
}


// ------------------------------------------------------------
// 06 — REQUIRE VALID RUNWAY TASK ID
// ------------------------------------------------------------

const taskId = response?.id;

if (
  typeof taskId !== "string" ||
  !uuidPattern.test(taskId)
) {
  throw new Error(
    "SAFETY STOP: Runway returned no valid task ID. " +
    "Investigate the existing dispatch before attempting regeneration."
  );
}


// ------------------------------------------------------------
// 07 — RETURN VERIFIED SUBMISSION
// ------------------------------------------------------------

return [
  {
    json: {
      ...request,

      reservation_id:
        request.reservation_id,

      dispatch_claimed:
        true,

      provider:
        "RUNWAY",

      provider_job_id:
        taskId,

      provider_estimated_credits:
        response.estimatedCost?.credits ?? null,

      provider_submission_response:
        response,

      resume_existing_provider_task:
        false,

      resumed_provider_task:
        false,

      job_status:
        "PROVIDER_JOB_SUBMITTED"
    },

    pairedItem: {
      item: 0
    }
  }
];

// AGENT-007 — Validate Generated Asset Candidate
//
// IMPORTANT:
// This is TECHNICAL / STRUCTURAL QC only.
// It does NOT mean a human has visually approved the asset.
//
// Human canonical approval still happens later.

const job = $json;

const qcNotes = [];

// ----------------------------------------------------
// HELPERS
// ----------------------------------------------------

function missing(value) {
  return (
    value === null ||
    value === undefined ||
    value === ""
  );
}

function isGenericAssetName(value) {
  if (!value || typeof value !== "string") {
    return true;
  }

  const text = value.trim();

  if (!text) {
    return true;
  }

  if (/^TMP_/i.test(text)) {
    return true;
  }

  if (
    /^Agent-\d+\s+approved\s+(new|reused)\s+asset$/i.test(text)
  ) {
    return true;
  }

  return false;
}

function sanitizeIdPart(value) {
  return String(value ?? "")
    .trim()
    .replace(/[^A-Za-z0-9_-]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
}

// ----------------------------------------------------
// CORE IDENTITY VALIDATION
// ----------------------------------------------------

if (missing(job.asset_creation_batch_id)) {
  qcNotes.push(
    "Missing asset_creation_batch_id."
  );
}

if (missing(job.production_readiness_manifest_id)) {
  qcNotes.push(
    "Missing production_readiness_manifest_id."
  );
}

if (missing(job.requirement_key)) {
  qcNotes.push(
    "Missing requirement_key."
  );
}

if (missing(job.requirement_type)) {
  qcNotes.push(
    "Missing requirement_type."
  );
}

if (missing(job.source_asset_id)) {
  qcNotes.push(
    "Missing source_asset_id."
  );
}

// ----------------------------------------------------
// SUPPORTED ASSET TYPE VALIDATION
// ----------------------------------------------------

const supportedTypes = [
  "PROP",
  "OVERLAY_VFX"
];

const assetType =
  job.normalized_asset_type ??
  job.requirement_type ??
  null;

if (!supportedTypes.includes(assetType)) {
  qcNotes.push(
    `Unsupported generated asset type: ${assetType ?? "UNKNOWN"}.`
  );
}

// ----------------------------------------------------
// HUMAN-READABLE NAME VALIDATION
// ----------------------------------------------------

const requestedName =
  job.requested_name ??
  job.creation_brief?.requested_name ??
  job.source_label ??
  null;

if (isGenericAssetName(requestedName)) {
  qcNotes.push(
    "Asset does not have a resolved human-readable name."
  );
}

// ----------------------------------------------------
// PROVIDER VALIDATION
// ----------------------------------------------------

if (missing(job.provider)) {
  qcNotes.push(
    "Missing provider."
  );
}

if (missing(job.provider_job_id)) {
  qcNotes.push(
    "Missing provider_job_id."
  );
}

// ----------------------------------------------------
// GENERATION SETTINGS VALIDATION
// ----------------------------------------------------

const settings =
  job.generation_settings_json ?? {};

const requiresTransparency =
  supportedTypes.includes(assetType);

if (requiresTransparency) {

  if (
    settings.transparent_background !== true
  ) {
    qcNotes.push(
      `${assetType} was not generated with transparent_background=true.`
    );
  }

  if (
    settings.background_requirement !==
    "transparent_background_required"
  ) {
    qcNotes.push(
      `${assetType} does not declare transparent_background_required.`
    );
  }
}

// ----------------------------------------------------
// OUTPUT VALIDATION
// ----------------------------------------------------

if (missing(job.output_source_url)) {
  qcNotes.push(
    "Missing provider output_source_url."
  );
}

if (missing(job.output_storage_path)) {
  qcNotes.push(
    "Missing durable Supabase output_storage_path."
  );
}

if (
  !missing(job.output_storage_path) &&
  !String(job.output_storage_path)
    .toLowerCase()
    .endsWith(".png")
) {
  qcNotes.push(
    "Generated visual asset is not stored as a PNG."
  );
}

// ----------------------------------------------------
// ATTEMPT VALIDATION
// ----------------------------------------------------

const attemptNumber =
  Number(job.attempt_number);

if (
  !Number.isInteger(attemptNumber) ||
  attemptNumber < 1
) {
  qcNotes.push(
    "Invalid attempt_number."
  );
}

// ----------------------------------------------------
// CANDIDATE ID
// ----------------------------------------------------

let candidateAssetId = null;

if (
  !missing(job.asset_creation_batch_id) &&
  !missing(assetType) &&
  !missing(job.source_asset_id) &&
  Number.isInteger(attemptNumber) &&
  attemptNumber >= 1
) {

  const sourcePart =
    sanitizeIdPart(job.source_asset_id);

  const typePart =
    sanitizeIdPart(assetType);

  candidateAssetId =
    `CAND-${job.asset_creation_batch_id}` +
    `-${typePart}` +
    `-${sourcePart}` +
    `-A${String(attemptNumber).padStart(2, "0")}`;
}

// ----------------------------------------------------
// FINAL QC STATUS
// ----------------------------------------------------

const qcStatus =
  qcNotes.length === 0
    ? "PASS"
    : "REVIEW_REQUIRED";

const jobStatus =
  qcStatus === "PASS"
    ? "QC_PASSED"
    : "QC_REVIEW_REQUIRED";

// ----------------------------------------------------
// FINAL OUTPUT
// ----------------------------------------------------

return {
  json: {
    ...job,

    candidate_asset_id:
      candidateAssetId,

    qc_status:
      qcStatus,

    qc_notes:
      qcNotes,

    qc_scope:
      "TECHNICAL_AND_STRUCTURAL_ONLY",

    transparency_required:
      requiresTransparency,

    // IMPORTANT:
    // Current AGENT-007 verifies that transparency
    // was REQUESTED in the generation settings.
    //
    // It does not yet inspect individual PNG pixels.
    transparency_pixel_verified:
      false,

    human_visual_qc_required:
      true,

    job_status:
      jobStatus,

    error_message:
      qcStatus === "PASS"
        ? null
        : qcNotes.join(" ")
  }
};

// AGENT-007 — Validate Complete Creation Batch
// Supports multiple attempts per requirement.
// Only the latest attempt determines the final result.

const rawJobs = $input.all().flatMap(item =>
  Array.isArray(item.json)
    ? item.json
    : [item.json]
);

const context =
  $('03B - Resume Existing Asset Creation Batch').first().json;

const expectedCount =
  Number(context.job_count ?? 0);

if (!Number.isInteger(expectedCount) || expectedCount <= 0) {
  throw new Error(
    "Invalid expected job count in AGENT-007 context."
  );
}

// ----------------------------------------------------
// VALIDATE SAVED RECORDS
// ----------------------------------------------------

if (rawJobs.length === 0) {
  throw new Error(
    "No saved asset creation jobs were found."
  );
}

for (const job of rawJobs) {

  if (
    job.asset_creation_batch_id !==
    context.asset_creation_batch_id
  ) {
    throw new Error(
      "A saved job belongs to the wrong batch."
    );
  }

  if (
    !job.requirement_key ||
    !String(job.requirement_key).trim()
  ) {
    throw new Error(
      "A saved job is missing requirement_key."
    );
  }

  const attempt = Number(job.attempt_number);

  if (!Number.isInteger(attempt) || attempt < 1) {
    throw new Error(
      `Invalid attempt number for ${job.requirement_key}.`
    );
  }
}

// ----------------------------------------------------
// GROUP JOBS BY REQUIREMENT KEY
// ----------------------------------------------------

const groupedJobs = new Map();

for (const job of rawJobs) {

  const key = job.requirement_key;

  if (!groupedJobs.has(key)) {
    groupedJobs.set(key, []);
  }

  groupedJobs.get(key).push(job);
}

// ----------------------------------------------------
// SELECT LATEST ATTEMPT FOR EACH REQUIREMENT
// ----------------------------------------------------

const latestJobs = [];

for (const [key, attempts] of groupedJobs.entries()) {

  attempts.sort(
    (a, b) =>
      Number(b.attempt_number) -
      Number(a.attempt_number)
  );

  if (
    attempts.length > 1 &&
    Number(attempts[0].attempt_number) ===
    Number(attempts[1].attempt_number)
  ) {
    throw new Error(
      `Duplicate attempt number detected for ${key}.`
    );
  }

  latestJobs.push(attempts[0]);
}

// ----------------------------------------------------
// VALIDATE FINAL REQUIREMENT COUNT
// ----------------------------------------------------

if (latestJobs.length !== expectedCount) {
  throw new Error(
    `AGENT-007 batch incomplete. Expected ${expectedCount} unique requirements but found ${latestJobs.length}.`
  );
}

// ----------------------------------------------------
// CATEGORIZE FINAL RESULTS
// ----------------------------------------------------

const passedJobs = latestJobs.filter(
  job =>
    job.qc_status === "PASS" &&
    Boolean(job.candidate_asset_id) &&
    Boolean(job.output_storage_path)
);

const failedJobs = latestJobs.filter(
  job =>
    job.job_status === "PROVIDER_FAILED" ||
    job.job_status === "UNSUPPORTED_ASSET_TYPE"
);

const reviewJobs = latestJobs.filter(
  job =>
    !passedJobs.includes(job) &&
    !failedJobs.includes(job)
);

// ----------------------------------------------------
// RETURN VALIDATED BATCH
// ----------------------------------------------------

return [
  {
    json: {
      asset_creation_batch_id:
        context.asset_creation_batch_id,

      production_readiness_manifest_id:
        context.production_readiness_manifest_id,

      asset_resolution_run_id:
        context.asset_resolution_run_id,

      production_plan_run_id:
        context.production_plan_run_id,

      episode_script_id:
        context.episode_script_id,

      episode_code:
        context.episode_code,

      script_version:
        context.script_version,

      title_working:
        context.title_working,

      expected_job_count:
        expectedCount,

      raw_saved_record_count:
        rawJobs.length,

      historical_attempt_count:
        rawJobs.length - latestJobs.length,

      saved_job_count:
        latestJobs.length,

      completed_job_count:
        passedJobs.length,

      review_job_count:
        reviewJobs.length,

      failed_job_count:
        failedJobs.length,

      validation_status:
        "PASS",

      // Only the latest attempt of each requirement.
      saved_jobs:
        latestJobs,

      agent_version:
        context.agent_version,

      prompt_version:
        context.prompt_version
    }
  }
];

// AGENT-007 — Build Director Brief
//
// IMPORTANT:
// Read the saved batch explicitly from Node 14 instead of
// relying on $input, which can contain stale execution data
// during manual recovery/testing.

const rawSavedBatch =
  $('14 - Save Asset Creation Batch').first().json;

const savedBatch =
  Array.isArray(rawSavedBatch)
    ? rawSavedBatch[0]
    : rawSavedBatch;

if (!savedBatch) {
  throw new Error(
    "AGENT-007 Director Brief could not find the saved asset creation batch from Node 14."
  );
}

const summary =
  savedBatch.summary_json ?? {};

const candidateAssets =
  Array.isArray(summary.candidate_assets)
    ? summary.candidate_assets
    : [];

const total =
  Number(
    savedBatch.job_count ?? 0
  );

const completed =
  Number(
    savedBatch.completed_job_count ?? 0
  );

const review =
  Number(
    savedBatch.review_job_count ?? 0
  );

const failed =
  Number(
    savedBatch.failed_job_count ?? 0
  );


// ------------------------------------------------------------
// SAFETY VALIDATION
// ------------------------------------------------------------

if (total <= 0) {
  throw new Error(
    "AGENT-007 Director Brief received an invalid job_count."
  );
}

if (completed + failed > total) {
  throw new Error(
    `AGENT-007 Director Brief received inconsistent counts: ${completed} completed + ${failed} failed > ${total} total.`
  );
}

if (candidateAssets.length !== completed) {
  throw new Error(
    `AGENT-007 Director Brief mismatch: ${completed} completed jobs were reported but ${candidateAssets.length} candidate assets were supplied.`
  );
}


// ------------------------------------------------------------
// NEXT ACTION
// ------------------------------------------------------------

const nextAction =
  summary.next_action ??
  (
    failed > 0
      ? "Human review required. One or more asset creation jobs failed and must be investigated."
      : "Human review and canonical approval required before rerunning AGENT-006."
  );


// ------------------------------------------------------------
// FINAL DIRECTOR BRIEF
// ------------------------------------------------------------

return [
  {
    json: {
      agent:
        "AGENT-007 — Asset Creation & Canonicalization Producer v0.1",

      asset_creation_batch_id:
        savedBatch.asset_creation_batch_id,

      production_readiness_manifest_id:
        savedBatch.production_readiness_manifest_id,

      asset_resolution_run_id:
        savedBatch.asset_resolution_run_id,

      episode_code:
        savedBatch.episode_code,

      script_version:
        savedBatch.script_version,

      title_working:
        savedBatch.title_working,

      job_count:
        total,

      completed_job_count:
        completed,

      review_job_count:
        review,

      failed_job_count:
        failed,

      batch_status:
        savedBatch.batch_status,

      candidate_assets:
        candidateAssets,

      human_approval_required:
        true,

      production_ready:
        false,

      next_action:
        nextAction,

      director_brief:
        `AGENT-007 completed batch ${savedBatch.asset_creation_batch_id}. ` +
        `${completed}/${total} authorised asset creation jobs produced REVIEW candidates. ` +
        `${review} candidate asset(s) require human canonical review. ` +
        `${failed} job(s) failed. ` +
        `No candidate has been canonically approved by AGENT-007. ` +
        `Human review is required before AGENT-006 is rerun.`
    }
  }
];

const row = $input.first().json;

const upstream =
  $('00 - Normalize Asset Creation Request').first().json;

const hasRow =
  row &&
  typeof row === 'object' &&
  Object.keys(row).length > 0 &&
  row.id;

// S6 (ENG-20260928-020): the persisted row must be the exact requested UUID.
const exactMatch =
  hasRow &&
  String(row.id).trim().toLowerCase() ===
    String(upstream.production_readiness_manifest_id).trim().toLowerCase();

if (!hasRow || !exactMatch) {
  return [
    {
      json: {
        production_readiness_manifest_id:
          upstream.production_readiness_manifest_id,

        status: null,
        readiness_state: null,
        readiness_manifest_json: null,

        agent_version: upstream.agent_version,
        prompt_version: upstream.prompt_version,

        manifest_source: 'SUPABASE',
        manifest_found: false,
        manifest_id_mismatch: Boolean(hasRow && !exactMatch)
      }
    }
  ];
}

return [
  {
    json: {
      production_readiness_manifest_id: row.id,

      status: row.status ?? null,
      readiness_state: row.readiness_state ?? null,
      readiness_manifest_json:
        row.readiness_manifest_json ?? null,

      agent_version: upstream.agent_version,
      prompt_version: upstream.prompt_version,

      manifest_source: 'SUPABASE',
      manifest_found: true
    }
  }
];

const job = $json;

const timestamp = Date.now();

return {
  json: {
    ...job,

    provider: "MOCK_IMAGE_PROVIDER",

    provider_job_id:
      `MOCKJOB-${timestamp}-${job.job_index}`,

    output_source_url:
      `https://mock.provider.local/output/${timestamp}/${job.job_index}`,

    output_storage_path:
      `mock://asset-output/${job.asset_creation_batch_id}/${job.temporary_asset_id ?? job.source_asset_id ?? "UNKNOWN"}.png`,

    generation_metadata_json: {
      mock: true,
      generated_at: new Date(timestamp).toISOString(),
      note: "Mock provider output for AGENT-007 parallel development."
    },

    job_status:
      "PROVIDER_OUTPUT_RECEIVED"
  }
};

