parameters.jsCode:
// AGENT-007 — NODE 07G
// Normalize Final Provider Output
//
// Supports newly submitted and resumed Runway tasks.
//
// SAFETY:
// - Retrieve the polling context linked to THIS input.
// - Never fall back to the first historical item.
// - Verify that the returned Runway task ID matches.
// - Stop if item linking is unavailable.
//
// No paid provider requests or database writes occur here.

const inputs = $input.all();

if (inputs.length !== 1) {
  throw new Error(
    `SAFETY STOP: Expected one Runway task, received ${inputs.length}.`
  );
}

const task = inputs[0].json;


// ------------------------------------------------------------
// 01 — RETRIEVE THE MATCHING POLLING CONTEXT
// ------------------------------------------------------------

let originalJob;

try {
  originalJob =
    $('07D2 - Prepare Runway Polling Context')
      .itemMatching(0)
      .json;
} catch (error) {
  throw new Error(
    "SAFETY STOP: Cannot trace this Runway response to " +
    "its original polling context. " +
    "Do not use .first() as a fallback. " +
    `Details: ${error.message}`
  );
}


// ------------------------------------------------------------
// 02 — VALIDATE ORIGINAL ASSET IDENTITY
// ------------------------------------------------------------

if (
  !originalJob ||
  !originalJob.asset_creation_batch_id ||
  !originalJob.production_readiness_manifest_id ||
  !originalJob.requirement_key ||
  !originalJob.source_asset_id ||
  !originalJob.provider_job_id
) {
  throw new Error(
    "SAFETY STOP: Matching polling context has incomplete asset identity."
  );
}

const attemptNumber =
  Number(originalJob.attempt_number);

if (
  !Number.isInteger(attemptNumber) ||
  attemptNumber < 1 ||
  attemptNumber > 3
) {
  throw new Error(
    "SAFETY STOP: Invalid attempt number in matching polling context."
  );
}


// ------------------------------------------------------------
// 03 — VERIFY THE EXACT RUNWAY TASK
// ------------------------------------------------------------

if (
  !task ||
  typeof task.id !== "string" ||
  !task.id
) {
  throw new Error(
    "SAFETY STOP: Runway response has no valid task ID."
  );
}

if (task.id !== originalJob.provider_job_id) {
  throw new Error(
    "SAFETY STOP: Runway task/asset mismatch. " +
    `Expected ${originalJob.provider_job_id}, ` +
    `received ${task.id}, ` +
    `asset ${originalJob.source_asset_id}.`
  );
}


// ------------------------------------------------------------
// 04 — VERIFY SUCCESSFUL PROVIDER COMPLETION
// ------------------------------------------------------------

if (task.status !== "SUCCEEDED") {
  throw new Error(
    "SAFETY STOP: Expected a successful Runway task. " +
    `Received ${task.status ?? "UNKNOWN"}.`
  );
}


// ------------------------------------------------------------
// 05 — VERIFY OUTPUT URL
// ------------------------------------------------------------

const outputUrl =
  Array.isArray(task.output)
    ? task.output[0]
    : null;

if (
  typeof outputUrl !== "string" ||
  !outputUrl.startsWith("https://")
) {
  throw new Error(
    "SAFETY STOP: Successful Runway task has no valid output URL."
  );
}


// ------------------------------------------------------------
// 06 — RETURN VERIFIED ASSET OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {
      ...originalJob,

      provider: "RUNWAY",

      provider_job_id: task.id,

      provider_task_status: task.status,

      output_source_url: outputUrl,

      output_urls: task.output,

      generation_metadata_json: {
        runway_task: task,

        resumed_provider_task:
          originalJob.resumed_provider_task === true,

        completed_at:
          new Date().toISOString()
      },

      job_status:
        "PROVIDER_OUTPUT_RECEIVED"
    },

    pairedItem: {
      item: 0
    }
  }
];

