parameters.jsCode:
// ============================================================
// AGENT-007 — NODE 07J
// Normalize Stored Asset Output
//
// PURPOSE:
// - Validate the Supabase Storage upload response.
// - Recover the exact originating asset job.
// - Preserve asset identity.
// - Record the durable storage path.
//
// SAFETY:
// - Exactly one upload response is required.
// - Uses itemMatching(0), never .first() or ambiguous .item.
// - Stops if storage identity cannot be verified.
// - No API calls or database writes occur here.
// ============================================================


// ------------------------------------------------------------
// 01 — REQUIRE EXACTLY ONE UPLOAD RESPONSE
// ------------------------------------------------------------

const inputs = $input.all();

if (inputs.length !== 1) {
  throw new Error(
    `SAFETY STOP: Expected exactly one Supabase upload response, received ${inputs.length}.`
  );
}

const upload = inputs[0].json;


// ------------------------------------------------------------
// 02 — RECOVER THE MATCHING ORIGINAL ASSET JOB
// ------------------------------------------------------------

let originalJob;

try {
  originalJob =
    $('07G - Normalize Final Provider Output')
      .itemMatching(0)
      .json;
} catch (error) {
  throw new Error(
    "SAFETY STOP: Cannot trace Supabase upload back to " +
    "its originating Runway asset. " +
    `Details: ${error.message}`
  );
}


// ------------------------------------------------------------
// 03 — VALIDATE ORIGINAL ASSET IDENTITY
// ------------------------------------------------------------

if (
  !originalJob ||
  !originalJob.asset_creation_batch_id ||
  !originalJob.production_readiness_manifest_id ||
  !originalJob.requirement_key ||
  !originalJob.source_asset_id ||
  !originalJob.provider_job_id
) {
  throw new Error(
    "SAFETY STOP: Original asset job has incomplete identity."
  );
}


// ------------------------------------------------------------
// 04 — VALIDATE SUPABASE STORAGE RESPONSE
// ------------------------------------------------------------

const storagePath =
  upload.Key ??
  upload.key ??
  null;

if (
  typeof storagePath !== "string" ||
  !storagePath.trim()
) {
  throw new Error(
    "SAFETY STOP: Supabase upload succeeded but no valid storage Key was returned."
  );
}


// ------------------------------------------------------------
// 05 — RETURN NORMALIZED STORED ASSET
// ------------------------------------------------------------

return [
  {
    json: {
      ...originalJob,

      storage_provider:
        "SUPABASE",

      storage_bucket:
        "production-assets",

      output_storage_path:
        storagePath,

      supabase_object_id:
        upload.Id ??
        upload.id ??
        null,

      storage_upload_response:
        upload,

      job_status:
        "PROVIDER_OUTPUT_STORED"
    },

    pairedItem: {
      item: 0
    }
  }
];

// AGENT-007 — NODE 07F3
// Normalize Runway Failure
//
// PURPOSE:
// Convert a confirmed terminal Runway failure into a
// persistable asset_creation_jobs failure record.
//
// SAFETY:
// - Match the current task to its linked polling context.
// - Never use .first() as a fallback.
// - Require an explicit, matching Runway task ID.
// - Accept only known terminal failure statuses.
// - Never classify UNKNOWN as a confirmed provider failure.
//
// This node makes no API requests or database writes.

const inputs = $input.all();

if (inputs.length !== 1) {
  throw new Error(
    `SAFETY STOP: Expected exactly one Runway failure response, received ${inputs.length}.`
  );
}

const task = inputs[0].json;


// ------------------------------------------------------------
// 01 — RETRIEVE THE MATCHING POLLING CONTEXT
// ------------------------------------------------------------

let originalJob;

try {
  originalJob =
    $('07D2 - Prepare Runway Polling Context')
      .itemMatching(0)
      .json;

} catch (error) {

  throw new Error(
    "SAFETY STOP: Cannot trace this Runway failure " +
    "to its original polling context. " +
    "Do not use .first() as a fallback. " +
    `Details: ${error.message}`
  );

}


// ------------------------------------------------------------
// 02 — VALIDATE ORIGINAL ASSET IDENTITY
// ------------------------------------------------------------

if (
  !originalJob ||
  !originalJob.asset_creation_batch_id ||
  !originalJob.production_readiness_manifest_id ||
  !originalJob.requirement_key ||
  !originalJob.source_asset_id ||
  !originalJob.provider_job_id
) {
  throw new Error(
    "SAFETY STOP: Matching polling context has incomplete asset identity."
  );
}

const attemptNumber =
  Number(originalJob.attempt_number);

if (
  !Number.isInteger(attemptNumber) ||
  attemptNumber < 1 ||
  attemptNumber > 3
) {
  throw new Error(
    "SAFETY STOP: Invalid attempt number in matching polling context."
  );
}


// ------------------------------------------------------------
// 03 — REQUIRE AN EXPLICIT RUNWAY TASK ID
// ------------------------------------------------------------

if (
  !task ||
  typeof task.id !== "string" ||
  !task.id.trim()
) {
  throw new Error(
    "SAFETY STOP: Runway failure response has no task ID. " +
    "The provider outcome must be investigated manually."
  );
}

const expectedTaskId =
  originalJob.provider_job_id;

const receivedTaskId =
  task.id;

if (receivedTaskId !== expectedTaskId) {
  throw new Error(
    "SAFETY STOP: Runway failure task mismatch. " +
    `Expected ${expectedTaskId}, ` +
    `received ${receivedTaskId}. ` +
    `Asset: ${originalJob.source_asset_id}.`
  );
}


// ------------------------------------------------------------
// 04 — REQUIRE A CONFIRMED TERMINAL FAILURE
// ------------------------------------------------------------

const providerStatus =
  typeof task.status === "string"
    ? task.status.trim().toUpperCase()
    : "UNKNOWN";

// Recognised terminal failure spellings.
// Extend this list only after verifying another status
// against the provider's actual API response.

const terminalFailureStatuses = new Set([
  "FAILED",
  "CANCELED",
  "CANCELLED"
]);

if (!terminalFailureStatuses.has(providerStatus)) {

  throw new Error(
    "SAFETY STOP: Cannot persist an unconfirmed " +
    "Runway failure. " +
    `Task: ${receivedTaskId}. ` +
    `Status: ${providerStatus}. ` +
    "Check the existing provider task before retrying."
  );

}


// ------------------------------------------------------------
// 05 — BUILD CONFIRMED FAILURE DETAILS
// ------------------------------------------------------------

const errorMessage =
  `Runway task ended with confirmed terminal status: ${providerStatus}`;

const failureDetails = {
  provider: "RUNWAY",

  task_id: receivedTaskId,

  status: providerStatus,

  raw_task: task,

  resumed_provider_task:
    originalJob.resumed_provider_task === true,

  failed_at:
    new Date().toISOString()
};


// ------------------------------------------------------------
// 06 — RETURN NORMALIZED FAILURE
// ------------------------------------------------------------

return [
  {
    json: {
      ...originalJob,

      provider:
        "RUNWAY",

      provider_job_id:
        receivedTaskId,

      provider_task_status:
        providerStatus,

      candidate_asset_id:
        null,

      output_source_url:
        null,

      output_storage_path:
        null,

      generation_metadata_json:
        failureDetails,

      job_status:
        "PROVIDER_FAILED",

      qc_status:
        "REVIEW_REQUIRED",

      qc_notes: [
        errorMessage
      ],

      error_message:
        errorMessage
    },

    pairedItem: {
      item: 0
    }
  }
];

const batch = $input.first().json;

const jobs = Array.isArray(batch.saved_jobs)
  ? batch.saved_jobs
  : [];


// ------------------------------------------------------------
// Build list of successful candidate assets
// ------------------------------------------------------------

const candidateAssets = jobs
  .filter(job =>
    job.qc_status === "PASS" &&
    job.candidate_asset_id
  )
  .map(job => ({
    requirement_key:
      job.requirement_key,

    source_asset_id:
      job.source_asset_id,

    source_label:
      job.source_label,

    asset_name:
      job.creation_brief_json?.requested_name ??
      job.source_label ??
      job.source_asset_id,

    requirement_type:
      job.requirement_type,

    candidate_asset_id:
      job.candidate_asset_id,

    asset_registry_status:
      "REVIEW",

    output_storage_path:
      job.output_storage_path,

    output_source_url:
      job.output_source_url,

    provider:
      job.provider
  }));


// ------------------------------------------------------------
// Use the validated counts from Node 12
// ------------------------------------------------------------

const completedJobCount =
  Number(
    batch.completed_job_count ??
    candidateAssets.length
  );

const qcReviewJobCount =
  Number(
    batch.review_job_count ?? 0
  );

const failedJobCount =
  Number(
    batch.failed_job_count ?? 0
  );


// ------------------------------------------------------------
// Safety check
// Every PASS job should have produced a candidate asset.
// ------------------------------------------------------------

if (candidateAssets.length !== completedJobCount) {
  throw new Error(
    `AGENT-007 summary mismatch. Node 12 reported ${completedJobCount} completed job(s), but only ${candidateAssets.length} candidate asset(s) were found.`
  );
}


// ------------------------------------------------------------
// All successful candidates are still REVIEW assets until
// a human approves them.
//
// Add any QC_REVIEW_REQUIRED jobs because those also need
// human attention.
// ------------------------------------------------------------

const reviewJobCount =
  candidateAssets.length +
  qcReviewJobCount;


// ------------------------------------------------------------
// Determine next human action
// ------------------------------------------------------------

let nextAction;

if (failedJobCount > 0) {
  nextAction =
    "Human review required. One or more asset creation jobs failed and must be investigated before the production batch can be considered complete.";
}
else if (qcReviewJobCount > 0) {
  nextAction =
    "Human review required. One or more asset creation jobs require QC review, and successful candidates require canonical approval before rerunning AGENT-006.";
}
else {
  nextAction =
    "Human review and canonical approval required before rerunning AGENT-006.";
}


// ------------------------------------------------------------
// Return batch summary
// ------------------------------------------------------------

return [
  {
    json: {
      asset_creation_batch_id:
        batch.asset_creation_batch_id,

      production_readiness_manifest_id:
        batch.production_readiness_manifest_id,

      asset_resolution_run_id:
        batch.asset_resolution_run_id,

      production_plan_run_id:
        batch.production_plan_run_id,

      episode_script_id:
        batch.episode_script_id,

      episode_code:
        batch.episode_code,

      script_version:
        batch.script_version,

      title_working:
        batch.title_working,

      job_count:
        jobs.length,

      completed_job_count:
        completedJobCount,

      review_job_count:
        reviewJobCount,

      failed_job_count:
        failedJobCount,

      batch_status:
        "REVIEW",

      candidate_assets:
        candidateAssets,

      agent_version:
        batch.agent_version,

      prompt_version:
        batch.prompt_version,

      human_approval_required:
        true,

      next_action:
        nextAction
    }
  }
];

// AGENT-007 — NODE 03B
// Resume Existing Asset Creation Batch
//
// Purpose:
// - Recover the existing production batch.
// - Skip completed asset requirements.
// - Preserve active provider tasks for resumption.
// - Stop on ambiguous histories that might cause duplicate
//   paid generation.
//
// This node does NOT submit any provider requests or write
// anything to Supabase.

const context =
  $('03 - Prepare Asset Creation Context').first().json;


// ------------------------------------------------------------
// 01 — VALIDATE AUTHORISED CONTEXT
// ------------------------------------------------------------

const manifestId =
  context.production_readiness_manifest_id;

const originalQueue =
  context.asset_creation_queue;

if (
  !manifestId ||
  !Array.isArray(originalQueue) ||
  originalQueue.length === 0
) {
  throw new Error(
    "AGENT-007: Missing manifest ID or authorised asset queue."
  );
}

const authorisedByKey = new Map();
const authorisedBySource = new Map();

for (const item of originalQueue) {
  const key = item.requirement_key;

  const sourceId =
    item.source_asset_id ??
    item.creation_brief?.temporary_asset_id;

  if (!key || !sourceId) {
    throw new Error(
      "AGENT-007: An authorised asset has no requirement key or source ID."
    );
  }

  if (
    authorisedByKey.has(key) ||
    authorisedBySource.has(sourceId)
  ) {
    throw new Error(
      `AGENT-007: Duplicate authorised asset identity: ${key}`
    );
  }

  authorisedByKey.set(key, item);
  authorisedBySource.set(sourceId, item);
}


// ------------------------------------------------------------
// 02 — NORMALISE NODE 03A RESPONSE
// ------------------------------------------------------------

const existingJobs = $input.all().flatMap(item => {
  const value = item.json;

  if (Array.isArray(value)) {
    return value;
  }

  if (
    value &&
    typeof value === "object" &&
    Object.keys(value).length > 0
  ) {
    return [value];
  }

  return [];
});


// ------------------------------------------------------------
// 03 — NO HISTORY: CREATE A NEW BATCH CONTEXT
// ------------------------------------------------------------

if (existingJobs.length === 0) {
  return [
    {
      json: {
        ...context,

        asset_creation_queue: originalQueue,

        job_count: originalQueue.length,
        remaining_job_count: originalQueue.length,

        completed_existing_job_count: 0,
        completed_existing_requirement_keys: [],
        completed_existing_source_asset_ids: [],

        resumable_existing_job_count: 0,
        historical_record_count: 0,
        latest_batch_record_count: 0,

        resumed_existing_batch: false,
        resume_source: "NEW_BATCH",

        batch_status: "IN_PROGRESS"
      }
    }
  ];
}


// ------------------------------------------------------------
// 04 — VALIDATE ALL HISTORICAL RECORDS
// ------------------------------------------------------------

for (const job of existingJobs) {
  if (
    !job ||
    job.production_readiness_manifest_id !== manifestId
  ) {
    throw new Error(
      "AGENT-007: Historical job belongs to a different readiness manifest."
    );
  }

  if (
    !job.asset_creation_batch_id ||
    !job.requirement_key ||
    !job.source_asset_id ||
    !job.created_at ||
    !Number.isFinite(Date.parse(job.created_at))
  ) {
    throw new Error(
      "AGENT-007: Historical job is missing required identity or timestamp fields."
    );
  }

  if (
    !Number.isInteger(job.attempt_number) ||
    job.attempt_number < 1 ||
    job.attempt_number > 3
  ) {
    throw new Error(
      `AGENT-007: Invalid attempt number for ${job.requirement_key}.`
    );
  }

  const authorised =
    authorisedByKey.get(job.requirement_key);

  if (
    !authorised ||
    authorised.source_asset_id !== job.source_asset_id
  ) {
    throw new Error(
      `AGENT-007: Historical asset does not match the authorised queue: ${job.requirement_key}`
    );
  }
}


// ------------------------------------------------------------
// 05 — IDENTIFY THE EXISTING BATCH
// ------------------------------------------------------------

// Fail closed if multiple batches exist for this manifest.
// A human must reconcile them before the workflow can choose
// which batch owns the generation history.

const batchIds = [
  ...new Set(
    existingJobs.map(job => job.asset_creation_batch_id)
  )
];

if (batchIds.length !== 1) {
  throw new Error(
    "AGENT-007: Multiple historical batches exist for this manifest. Manual reconciliation required before generation."
  );
}

const existingBatchId = batchIds[0];

const batchJobs = existingJobs
  .filter(
    job => job.asset_creation_batch_id === existingBatchId
  )
  .sort(
    (a, b) =>
      Date.parse(b.created_at) -
      Date.parse(a.created_at)
  );


// ------------------------------------------------------------
// 06 — GROUP HISTORICAL ATTEMPTS BY REQUIREMENT
// ------------------------------------------------------------

const jobsByRequirement = new Map();

for (const job of batchJobs) {
  const key = job.requirement_key;

  if (!jobsByRequirement.has(key)) {
    jobsByRequirement.set(key, []);
  }

  jobsByRequirement.get(key).push(job);
}


// ------------------------------------------------------------
// 07 — CLASSIFY EACH AUTHORISED REQUIREMENT
// ------------------------------------------------------------

const remainingQueue = [];

const completedKeys = [];
const completedSources = [];

let resumableCount = 0;

const activeStatuses = new Set([
  "PROVIDER_JOB_SUBMITTED",
  "PROVIDER_IN_PROGRESS",
  "WAITING_FOR_PROVIDER"
]);

const retryableStatuses = new Set([
  "PROVIDER_FAILED",
  "QC_FAILED"
]);

for (const item of originalQueue) {
  const key = item.requirement_key;

  const history =
    jobsByRequirement.get(key) ?? [];

  if (history.length === 0) {
    remainingQueue.push(item);
    continue;
  }

  // Reject duplicate records for the same requirement/attempt.
  const seenAttempts = new Set();

  for (const job of history) {
    if (seenAttempts.has(job.attempt_number)) {
      throw new Error(
        `AGENT-007: Duplicate saved attempt for ${key}, attempt ${job.attempt_number}.`
      );
    }

    seenAttempts.add(job.attempt_number);
  }

  // Highest attempt wins when evaluating the latest state.
  history.sort(
    (a, b) =>
      b.attempt_number - a.attempt_number ||
      Date.parse(b.created_at) -
        Date.parse(a.created_at)
  );

  const latest = history[0];

  // Completed means a persisted candidate passed technical QC.
  // It does NOT mean the human has approved the asset.

  const passedJobs = history.filter(
    job => job.qc_status === "PASS"
  );

  if (passedJobs.length > 1) {
    throw new Error(
      `AGENT-007: Multiple passed candidates exist for ${key}. Manual reconciliation required.`
    );
  }

  if (passedJobs.length === 1) {
    const passed = passedJobs[0];

    if (
      passed.job_status !== "QC_PASSED" ||
      !passed.candidate_asset_id ||
      !passed.output_storage_path
    ) {
      throw new Error(
        `AGENT-007: Incomplete PASS record for ${key}.`
      );
    }

    if (latest.id !== passed.id) {
      throw new Error(
        `AGENT-007: A newer attempt exists after the passed candidate for ${key}. Manual reconciliation required.`
      );
    }

    completedKeys.push(key);
    completedSources.push(item.source_asset_id);

    continue;
  }

  // A QC_PASSED status without qc_status PASS is inconsistent.
  if (history.some(job => job.job_status === "QC_PASSED")) {
    throw new Error(
      `AGENT-007: Inconsistent QC status for ${key}.`
    );
  }

  // An older attempt must not still have an active provider task.
  // Otherwise two paid tasks might exist for the same asset.
  if (
    history.slice(1).some(
      job => activeStatuses.has(job.job_status)
    )
  ) {
    throw new Error(
      `AGENT-007: An older provider task is still active for ${key}. Manual reconciliation required.`
    );
  }

  // Existing active task: keep the requirement in the queue.
  // Node 05A must reuse its saved provider_job_id.
  if (activeStatuses.has(latest.job_status)) {
    if (!latest.provider_job_id) {
      throw new Error(
        `AGENT-007: Active provider task has no saved task ID for ${key}. Do not resubmit.`
      );
    }

    resumableCount += 1;
    remainingQueue.push(item);

    continue;
  }

  // Failed attempt: only retry if the failure is unambiguous.
  if (retryableStatuses.has(latest.job_status)) {
    const failureDetails = [
      latest.error_message ?? "",
      ...(Array.isArray(latest.qc_notes)
        ? latest.qc_notes
        : [])
    ].join(" ");

    if (
      latest.job_status === "PROVIDER_FAILED" &&
      (
        !failureDetails.trim() ||
        /UNKNOWN|TIMEOUT|TIMED OUT|UNCERTAIN|INDETERMINATE/i
          .test(failureDetails)
      )
    ) {
      throw new Error(
        `AGENT-007: Provider outcome is uncertain for ${key}. Inspect the saved Runway task before retrying.`
      );
    }

    if (latest.attempt_number >= 3) {
      throw new Error(
        `AGENT-007: Maximum attempts reached for ${key}.`
      );
    }

    remainingQueue.push(item);

    continue;
  }

  // Never silently regenerate an unrecognised state.
  throw new Error(
    `AGENT-007: Unrecognised or review-required job status "${latest.job_status}" for ${key}. Manual reconciliation required.`
  );
}


// ------------------------------------------------------------
// 08 — VALIDATE RECONCILED COUNTS
// ------------------------------------------------------------

if (
  completedKeys.length + remainingQueue.length !==
  originalQueue.length
) {
  throw new Error(
    "AGENT-007: Reconciled job counts do not match the authorised queue."
  );
}


// ------------------------------------------------------------
// 09 — RETURN RECOVERED CONTEXT
// ------------------------------------------------------------

return [
  {
    json: {
      ...context,

      asset_creation_batch_id:
        existingBatchId,

      asset_creation_queue:
        remainingQueue,

      job_count:
        originalQueue.length,

      remaining_job_count:
        remainingQueue.length,

      completed_existing_job_count:
        completedKeys.length,

      completed_existing_requirement_keys:
        completedKeys,

      completed_existing_source_asset_ids:
        completedSources,

      resumable_existing_job_count:
        resumableCount,

      historical_record_count:
        existingJobs.length,

      latest_batch_record_count:
        batchJobs.length,

      resumed_existing_batch:
        true,

      resume_source:
        "EXISTING_BATCH",

      batch_status:
        "IN_PROGRESS"
    }
  }
];

// ============================================================
// AGENT-007 — NODE 07F4
// Enforce Runway Polling Timeout
// Version: v0.1 — Complete Replacement
//
// PURPOSE:
// - Validate the Runway task response.
// - Preserve the original Runway task identity.
// - Restore provider_job_id for the next polling cycle.
// - Enforce a maximum polling duration of 5 minutes.
// - Prevent accidental polling of a different task.
//
// SAFETY:
// - No API calls.
// - No database writes.
// - No new generation requests.
// - Never resets the polling timer.
// ============================================================


// ------------------------------------------------------------
// 01 — REQUIRE EXACTLY ONE INPUT
// ------------------------------------------------------------

const inputs = $input.all();

if (inputs.length !== 1) {
  throw new Error(
    `SAFETY STOP: Expected exactly one Runway task, received ${inputs.length}.`
  );
}

const task = inputs[0].json;


// ------------------------------------------------------------
// 02 — DEFINE POLLING LIMIT
// ------------------------------------------------------------

const MAX_POLLING_MS = 5 * 60 * 1000;


// ------------------------------------------------------------
// 03 — VALIDATE RUNWAY TASK ID
// ------------------------------------------------------------

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (
  typeof task.id !== "string" ||
  !uuidPattern.test(task.id)
) {
  throw new Error(
    "SAFETY STOP: Runway polling response contains an invalid task ID."
  );
}


// ------------------------------------------------------------
// 04 — PREVENT TASK ID MISMATCH
// ------------------------------------------------------------

// If provider_job_id is already present, it must match
// the task ID returned by Runway.

if (
  task.provider_job_id != null &&
  task.provider_job_id !== task.id
) {
  throw new Error(
    "SAFETY STOP: Runway task ID does not match provider_job_id."
  );
}


// ------------------------------------------------------------
// 05 — VALIDATE ORIGINAL CREATION TIMESTAMP
// ------------------------------------------------------------

if (
  typeof task.createdAt !== "string" ||
  !task.createdAt.trim()
) {
  throw new Error(
    `SAFETY STOP: Runway task ${task.id} has no valid createdAt timestamp.`
  );
}

const createdAt = Date.parse(task.createdAt);

if (!Number.isFinite(createdAt)) {
  throw new Error(
    `SAFETY STOP: Invalid creation timestamp for Runway task ${task.id}.`
  );
}


// ------------------------------------------------------------
// 06 — CALCULATE ELAPSED TIME
// ------------------------------------------------------------

// Important:
// This uses the original creation time from Runway.
//
// It does NOT restart the timer each time the
// polling loop executes.

const elapsedMs = Date.now() - createdAt;

if (elapsedMs < 0) {
  throw new Error(
    `SAFETY STOP: Runway task ${task.id} has a future creation timestamp.`
  );
}


// ------------------------------------------------------------
// 07 — ENFORCE FIVE-MINUTE TIMEOUT
// ------------------------------------------------------------

if (elapsedMs >= MAX_POLLING_MS) {
  throw new Error(
    `POLLING TIMEOUT: Runway task ${task.id} has exceeded 5 minutes. ` +
    `Last reported status: ${task.status ?? "UNKNOWN"}. ` +
    "Check the existing Runway task before attempting regeneration. " +
    "Do not submit a new generation request automatically."
  );
}


// ------------------------------------------------------------
// 08 — PRESERVE TASK AND RESTORE POLLING IDENTITY
// ------------------------------------------------------------

// Runway returns its task ID as "id".
//
// Node 07E expects "provider_job_id".
//
// We preserve the full response and explicitly restore
// provider_job_id so the next polling cycle uses the
// SAME Runway task.

return [
  {
    json: {

      ...task,

      provider:
        "RUNWAY",

      provider_job_id:
        task.id,

      polling_elapsed_seconds:
        Math.floor(elapsedMs / 1000),

      polling_timeout_seconds:
        300

    },

    pairedItem: {
      item: 0
    }
  }
];

// AGENT-007 — NODE 05A
// Determine Asset Creation Attempt
//
// Responsibilities:
// 1. Never regenerate a completed requirement.
// 2. Resume an existing active provider task.
// 3. Stop if provider state is uncertain.
// 4. Calculate the next attempt only after a known failure.
// 5. Enforce the paid-attempt policy (S6, ENG-20260928-020, R-015):
//    MAX_PAID_ATTEMPTS_PER_REQUIREMENT = 1. A new paid attempt 2+ is never
//    automatic; it requires a separate future human authorisation. Resuming an
//    already-submitted provider task (step 08) is still allowed.
//
// This node performs no API calls and no database writes.

const inputs = $input.all();

if (inputs.length !== 1) {
  throw new Error(
    `AGENT-007: Expected exactly one asset job, received ${inputs.length}.`
  );
}

const job = inputs[0].json;

// Historical records up to attempt 3 remain valid evidence (read-only validation).
const HISTORICAL_ATTEMPT_CEILING = 3;

// New paid generation attempts permitted per requirement without new human authorisation.
const MAX_PAID_ATTEMPTS_PER_REQUIREMENT = 1;

const activeStatuses = new Set([
  "PROVIDER_JOB_SUBMITTED",
  "PROVIDER_IN_PROGRESS",
  "WAITING_FOR_PROVIDER"
]);

const retryableStatuses = new Set([
  "PROVIDER_FAILED",
  "QC_FAILED"
]);


// ------------------------------------------------------------
// 01 — VALIDATE CURRENT JOB
// ------------------------------------------------------------

if (
  !job.asset_creation_batch_id ||
  !job.production_readiness_manifest_id ||
  !job.requirement_key ||
  !job.source_asset_id
) {
  throw new Error(
    "AGENT-007: Cannot determine attempt because batch, manifest, or asset identity is missing."
  );
}


// ------------------------------------------------------------
// 02 — READ PERSISTED HISTORY FROM NODE 03A
// ------------------------------------------------------------

const existingJobs =
  $('03A - Get Existing Asset Creation Jobs')
    .all()
    .flatMap(item => {
      const value = item.json;

      if (Array.isArray(value)) {
        return value;
      }

      if (
        value &&
        typeof value === "object" &&
        Object.keys(value).length > 0
      ) {
        return [value];
      }

      return [];
    });


// ------------------------------------------------------------
// 03 — VALIDATE HISTORY AND SELECT THIS REQUIREMENT
// ------------------------------------------------------------

for (const record of existingJobs) {
  if (
    record.production_readiness_manifest_id !==
    job.production_readiness_manifest_id
  ) {
    throw new Error(
      "AGENT-007: Historical job belongs to a different readiness manifest."
    );
  }

  if (
    !record.asset_creation_batch_id ||
    !record.requirement_key ||
    !record.source_asset_id
  ) {
    throw new Error(
      "AGENT-007: Historical job has incomplete identity."
    );
  }
}

const previousAttempts = existingJobs
  .filter(record =>
    record.asset_creation_batch_id ===
      job.asset_creation_batch_id &&
    record.requirement_key ===
      job.requirement_key
  )
  .sort((a, b) =>
    Number(b.attempt_number) -
    Number(a.attempt_number)
  );


// ------------------------------------------------------------
// 04 — VALIDATE SAVED ATTEMPTS
// ------------------------------------------------------------

const seenAttempts = new Set();

for (const record of previousAttempts) {
  const attempt = Number(record.attempt_number);

  if (
    !Number.isInteger(attempt) ||
    attempt < 1 ||
    attempt > HISTORICAL_ATTEMPT_CEILING
  ) {
    throw new Error(
      `AGENT-007: Invalid historical attempt for ${job.requirement_key}.`
    );
  }

  if (seenAttempts.has(attempt)) {
    throw new Error(
      `AGENT-007: Duplicate attempt ${attempt} for ${job.requirement_key}.`
    );
  }

  if (record.source_asset_id !== job.source_asset_id) {
    throw new Error(
      `AGENT-007: Historical source asset mismatch for ${job.requirement_key}.`
    );
  }

  seenAttempts.add(attempt);
}


// ------------------------------------------------------------
// 05 — NEVER REGENERATE A COMPLETED REQUIREMENT
// ------------------------------------------------------------

const passedJobs = previousAttempts.filter(
  record =>
    record.qc_status === "PASS" ||
    record.job_status === "QC_PASSED"
);

if (passedJobs.length > 0) {
  throw new Error(
    `SAFETY STOP: ${job.source_asset_id} already has a ` +
    `completed or potentially completed candidate in batch ` +
    `${job.asset_creation_batch_id}. Do not generate it again.`
  );
}


// ------------------------------------------------------------
// 06 — INSPECT THE LATEST SAVED ATTEMPT
// ------------------------------------------------------------

const latestAttempt =
  previousAttempts.length > 0
    ? previousAttempts[0]
    : null;

const highestAttempt =
  latestAttempt
    ? Number(latestAttempt.attempt_number)
    : 0;

const latestStatus =
  latestAttempt
    ? String(latestAttempt.job_status ?? "")
    : "";


// ------------------------------------------------------------
// 07 — STOP IF AN OLDER PROVIDER TASK IS STILL ACTIVE
// ------------------------------------------------------------

if (
  previousAttempts.slice(1).some(
    record =>
      activeStatuses.has(
        String(record.job_status ?? "")
      )
  )
) {
  throw new Error(
    `SAFETY STOP: An older provider task is still active ` +
    `for ${job.source_asset_id}. Manual reconciliation required.`
  );
}


// ------------------------------------------------------------
// 08 — RESUME AN EXISTING ACTIVE PROVIDER TASK
// ------------------------------------------------------------

if (latestAttempt && activeStatuses.has(latestStatus)) {

  if (!latestAttempt.provider_job_id) {
    throw new Error(
      `SAFETY STOP: ${job.source_asset_id} has an active ` +
      `provider record without a provider_job_id. ` +
      `Do not submit another paid generation request.`
    );
  }

  return [
    {
      json: {
        ...job,

        attempt_number:
          highestAttempt,

        previous_attempt_count:
          previousAttempts.length,

        retry_required:
          false,

        resume_existing_provider_task:
          true,

        resume_provider_job_id:
          latestAttempt.provider_job_id,

        resume_source_job_record_id:
          latestAttempt.id ?? null,

        attempt_source:
          "EXISTING_PROVIDER_TASK"
      }
    }
  ];
}


// ------------------------------------------------------------
// 09 — INSPECT A PREVIOUS FAILURE BEFORE RETRYING
// ------------------------------------------------------------

if (latestAttempt) {

  if (!retryableStatuses.has(latestStatus)) {
    throw new Error(
      `SAFETY STOP: Unexpected job status "${latestStatus}" ` +
      `for ${job.source_asset_id}. Manual reconciliation required.`
    );
  }

  if (latestStatus === "PROVIDER_FAILED") {

    const failureDetails = [
      latestAttempt.error_message ?? "",
      ...(Array.isArray(latestAttempt.qc_notes)
        ? latestAttempt.qc_notes
        : [])
    ].join(" ");

    if (
      !failureDetails.trim() ||
      /UNKNOWN|TIMEOUT|TIMED OUT|UNCERTAIN|INDETERMINATE/i
        .test(failureDetails)
    ) {
      throw new Error(
        `SAFETY STOP: The previous provider outcome is ` +
        `uncertain for ${job.source_asset_id}. ` +
        `Inspect the saved Runway task before retrying.`
      );
    }
  }
}


// ------------------------------------------------------------
// 10 — CALCULATE THE NEXT GENERATION ATTEMPT
// ------------------------------------------------------------

const nextAttempt = highestAttempt + 1;

if (nextAttempt > MAX_PAID_ATTEMPTS_PER_REQUIREMENT) {
  throw new Error(
    `SAFETY STOP (PAID_ATTEMPT_LIMIT): ${job.source_asset_id} would need paid ` +
    `generation attempt ${nextAttempt}, but MAX_PAID_ATTEMPTS_PER_REQUIREMENT is ` +
    `${MAX_PAID_ATTEMPTS_PER_REQUIREMENT}. A further paid attempt requires a ` +
    `separate human authorisation. Stopped before reservation; no writes.`
  );
}


// ------------------------------------------------------------
// 11 — RETURN NEW-ATTEMPT CONTEXT
// ------------------------------------------------------------

return [
  {
    json: {
      ...job,

      attempt_number:
        nextAttempt,

      previous_attempt_count:
        previousAttempts.length,

      retry_required:
        nextAttempt > 1,

      resume_existing_provider_task:
        false,

      resume_provider_job_id:
        null,

      resume_source_job_record_id:
        null,

      attempt_source:
        "SUPABASE_HISTORY"
    }
  }
];

// AGENT-007 — Resume Existing Runway Task

const job = $json;

if (
  job.resume_existing_provider_task !== true
) {
  throw new Error(
    "Resume node received a job that is not marked for provider-task resume."
  );
}

if (!job.resume_provider_job_id) {
  throw new Error(
    "Cannot resume Runway task because resume_provider_job_id is missing."
  );
}

return {
  json: {
    ...job,

    provider:
      "RUNWAY",

    provider_job_id:
      job.resume_provider_job_id,

    job_status:
      "PROVIDER_JOB_SUBMITTED",

    resumed_provider_task:
      true
  }
};

// AGENT-007 — Normalize Submission Checkpoint
//
// Converts a Supabase checkpoint response into
// a complete Runway polling context.
//
// Works with real Supabase responses and simulated
// checkpoint records.
//
// Does not call Runway or write to Supabase.

const rawSaved = $input.first().json;

const saved = Array.isArray(rawSaved)
  ? rawSaved[0]
  : rawSaved;


// ----------------------------------------------------
// VALIDATE CHECKPOINT RECORD
// ----------------------------------------------------

if (!saved || typeof saved !== "object") {
  throw new Error(
    "SAFETY STOP: No valid submission checkpoint received."
  );
}

if (!saved.id) {
  throw new Error(
    "SAFETY STOP: Checkpoint has no database record ID."
  );
}

if (!saved.asset_creation_batch_id) {
  throw new Error(
    "SAFETY STOP: Missing asset_creation_batch_id."
  );
}

if (!saved.production_readiness_manifest_id) {
  throw new Error(
    "SAFETY STOP: Missing production_readiness_manifest_id."
  );
}

if (!saved.requirement_key) {
  throw new Error(
    "SAFETY STOP: Missing requirement_key."
  );
}

if (!saved.requirement_type) {
