//   - the requirement is still in the persisted creation queue and still CREATE_NEW
//   - no APPROVED/LOCKED canonical asset already satisfies the requirement
//   - attempt_number <= MAX_PAID_ATTEMPTS_PER_REQUIREMENT (1)
//   - not an existing provider task (resume uses 07A2, never this path)

const PAID_DISPATCH_SWITCH = 'DISABLED';
const MAX_PAID_ATTEMPTS_PER_REQUIREMENT = 1;

// No persisted authorisation source is wired in this draft (the proposed
// paid_generation_authorisations table awaits Company Brain approval).
const persistedAuthorisation = null;

let job;

try {
  job =
    $('07A - Prepare Image Generation Request')
      .itemMatching(0)
      .json;
} catch (error) {
  throw new Error(
    'SAFETY STOP: paid dispatch gate cannot match its job context. ' +
    error.message
  );
}

const requested =
  $('00 - Normalize Asset Creation Request').first().json;

const manifestRow =
  $('01D - Normalize Real Readiness Manifest').first().json;

const manifest =
  manifestRow.readiness_manifest_json &&
  typeof manifestRow.readiness_manifest_json === 'object'
    ? manifestRow.readiness_manifest_json
    : {};

const registryRows =
  $input
    .all()
    .map(item => item.json)
    .filter(row => row && typeof row.asset_id === 'string');

const reasons = [];

if (PAID_DISPATCH_SWITCH !== 'ENABLED') {
  reasons.push('PAID_DISPATCH_SWITCH_DISABLED');
}

if (!persistedAuthorisation) {
  reasons.push('NO_PERSISTED_PAID_GENERATION_AUTHORISATION');
}

if (
  manifestRow.manifest_source !== 'SUPABASE' ||
  manifestRow.manifest_found !== true
) {
  reasons.push('READINESS_MANIFEST_NOT_FROM_SUPABASE');
}

if (manifestRow.status !== 'APPROVED') {
  reasons.push('READINESS_MANIFEST_NOT_APPROVED');
}

if (manifestRow.readiness_state !== 'NEEDS_ASSET_CREATION') {
  reasons.push('READINESS_STATE_NOT_NEEDS_ASSET_CREATION');
}

if (
  String(manifestRow.production_readiness_manifest_id) !==
    String(requested.production_readiness_manifest_id) ||
  String(job.production_readiness_manifest_id) !==
    String(requested.production_readiness_manifest_id)
) {
  reasons.push('READINESS_MANIFEST_ID_MISMATCH');
}

const queue =
  Array.isArray(manifest.asset_creation_queue)
    ? manifest.asset_creation_queue
    : [];

const inPersistedQueue =
  queue.some(
    item =>
      item &&
      item.requirement_key === job.requirement_key &&
      item.source_asset_id === job.source_asset_id
  );

if (!inPersistedQueue) {
  reasons.push('REQUIREMENT_NOT_IN_PERSISTED_CREATION_QUEUE');
}

const records =
  Array.isArray(manifest.all_resolution_records)
    ? manifest.all_resolution_records
    : [];

const record =
  records.find(item => item && item.requirement_key === job.requirement_key);

if (record && record.resolution_status !== 'CREATE_NEW') {
  reasons.push(`REQUIREMENT_NOT_CREATE_NEW:${record.resolution_status}`);
}

function normalize(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ');
}

const target = normalize(job.source_asset_id);

const canonicalMatches =
  registryRows.filter(row => {
    const status = String(row.status ?? '').trim();
    if (status !== 'APPROVED' && status !== 'LOCKED') return false;
    const tokens = [
      row.asset_id,
      row.asset_name,
      ...(Array.isArray(row.aliases) ? row.aliases : [])
    ].map(normalize);
    return target && tokens.includes(target);
  });

if (canonicalMatches.length > 0) {
  reasons.push(
