    canonicalMatches.map(row => row.asset_id).join(',')
  );
}

const attempt = Number(job.attempt_number);

if (
  !Number.isInteger(attempt) ||
  attempt < 1 ||
  attempt > MAX_PAID_ATTEMPTS_PER_REQUIREMENT
) {
  reasons.push(
    `PAID_ATTEMPT_${job.attempt_number}_EXCEEDS_MAX_${MAX_PAID_ATTEMPTS_PER_REQUIREMENT}`
  );
}

if (
  job.resume_existing_provider_task === true ||
  job.resumed_provider_task === true ||
  job.resume_provider_job_id ||
  job.provider_job_id
) {
  reasons.push('EXISTING_PROVIDER_TASK_IN_NEW_PAID_PATH');
}

return [
  {
    json: {
      ...job,

      paid_dispatch_authorised:
        reasons.length === 0,

