// AGENT-007 — Build Current Asset Creation Brief
// Reusable across episodes and asset creation attempts.
//
// Attempt numbers are supplied by Node 05A.
// This node must never hard-code an episode-specific retry.

const job = $json;

const brief = job.creation_brief ?? {};

const requirementType =
  job.requirement_type ??
  brief.asset_type ??
  null;

const supportedTypes = [
  "PROP",
  "OVERLAY_VFX"
];

const supported =
  supportedTypes.includes(requirementType);


// ----------------------------------------------------
// SOURCE CONSTRAINTS
// ----------------------------------------------------

const rawConstraints =
  Array.isArray(brief.constraints)
    ? brief.constraints
    : [];


// Remove governance and database instructions that
// should not be sent to the image-generation provider.
//
// AGENT-007 registers REVIEW candidates only.
// Human canonical approval happens separately.

const providerConstraints =
  rawConstraints.filter(constraint => {

    const text =
      String(constraint ?? "")
        .toLowerCase()
        .trim();

    if (!text) {
      return false;
    }

    // Remove instructions telling the provider
    // to approve or lock generated assets.

    if (
      text.includes("register the finished asset") &&
      (
        text.includes("approved") ||
        text.includes("locked")
      )
    ) {
      return false;
    }

    // Remove database and registry alias instructions.

    if (
      text.includes("registry aliases") ||
      (
        text.includes("aliases field") &&
        text.includes("agent-006")
      )
    ) {
      return false;
    }

    return true;
  });


// ----------------------------------------------------
// ASSET NAME NORMALIZATION
// ----------------------------------------------------

const temporaryAssetId =
  brief.temporary_asset_id ??
  job.source_asset_id ??
  null;

const sourceLabels =
  Array.isArray(brief.source_labels)
    ? brief.source_labels
    : [];


// Detect generic workflow labels that should not
// become the human-readable asset name.

function isGenericLabel(value) {

  if (!value || typeof value !== "string") {
    return true;
  }

  const text = value.trim();

  if (!text) {
    return true;
  }

  if (/^TMP_/i.test(text)) {
    return true;
  }

  if (
    /^Agent-\d+\s+approved\s+(new|reused)\s+asset$/i.test(text)
  ) {
    return true;
  }

  return false;
}


// Convert a temporary asset ID into a readable name.
//
// Example:
// TMP_EP005_BERRY_SMUDGE_OVERLAYS
// becomes:
// Berry smudge overlays

function humanizeAssetId(value) {

  if (!value) {
    return null;
  }

  let text = String(value)
    .replace(/^TMP_/i, "")
    .replace(/^EP\d+_/i, "")
    .replace(/_/g, " ")
    .trim()
    .toLowerCase();

  if (!text) {
    return null;
  }

  return (
    text.charAt(0).toUpperCase() +
    text.slice(1)
  );
}


// Normalize words for comparing possible names.

function normalizeWords(value) {

  return String(value ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean);

}


const fallbackName =
  humanizeAssetId(temporaryAssetId);

const fallbackWords =
  normalizeWords(fallbackName);


// Collect meaningful candidate names.

const candidateLabels = [
  brief.requested_name,
  ...sourceLabels
]
  .filter(value => !isGenericLabel(value))
  .map(value => String(value).trim());


// Remove duplicate names.

const uniqueLabels =
  [...new Set(candidateLabels)];


// Search for an exact readable match.

const exactMatch =
  fallbackName
    ? uniqueLabels.find(
        label =>
          normalizeWords(label).join(" ") ===
          fallbackWords.join(" ")
      )
    : null;


// Allow useful descriptive additions.
//
// Example:
// Hand mirror → Tiny hand mirror
//
// Avoid contextual or count-specific words.

const unwantedExtraWords = new Set([
  "one",
  "two",
  "three",
  "four",
  "five",
  "current",
  "final",
  "selected",
  "reflected",
  "mikko",
  "lumi",
  "cheek",
  "nose",
  "mouth",
  "skin",
  "face",
  "state",
  "mask"
]);


let enhancedMatch = null;

if (fallbackWords.length > 0) {

  const exactIndex =
    exactMatch
      ? uniqueLabels.indexOf(exactMatch)
      : Infinity;

  for (let i = 0; i < uniqueLabels.length; i++) {

    if (i >= exactIndex) {
      break;
    }

    const label = uniqueLabels[i];

    const words =
      normalizeWords(label);

    const containsAllFallbackWords =
      fallbackWords.every(word =>
        words.includes(word)
      );

    if (!containsAllFallbackWords) {
      continue;
    }

    const extraWords =
      words.filter(
        word => !fallbackWords.includes(word)
      );

    const hasBadExtraWord =
      extraWords.some(word =>
        unwantedExtraWords.has(word)
      );

    if (
      extraWords.length <= 2 &&
      !hasBadExtraWord
    ) {
      enhancedMatch = label;
      break;
    }
  }
}


// ----------------------------------------------------
// FINAL HUMAN-READABLE NAME
// ----------------------------------------------------

const resolvedRequestedName =
  enhancedMatch ??
  exactMatch ??
  fallbackName ??
  uniqueLabels[0] ??
  job.source_label ??
  null;


// ----------------------------------------------------
// ATTEMPT NUMBER — AUTOMATIC
// ----------------------------------------------------
//
// Node 05A determines the correct attempt number
// using previous Supabase records.
//
// This node validates the value.
//
// Do not hard-code asset names or attempt numbers here.

const resolvedAttemptNumber =
  Number(job.attempt_number);

if (
  !Number.isInteger(resolvedAttemptNumber) ||
  resolvedAttemptNumber < 1 ||
  resolvedAttemptNumber > 3
) {
  throw new Error(
    `AGENT-007 invalid attempt number for ` +
    `${temporaryAssetId ?? "UNKNOWN"}. ` +
    `Received: ${job.attempt_number ?? "MISSING"}. ` +
    `Check Node 05A.`
  );
}


// ----------------------------------------------------
// FINAL NORMALIZED JOB
// ----------------------------------------------------

return {
  json: {
    ...job,

    normalized_asset_type:
      requirementType,

    requested_name:
      resolvedRequestedName,

    // Preserve the cleaned asset name and constraints
    // for downstream database registration.

    creation_brief: {
      ...brief,

      requested_name:
        resolvedRequestedName,

      temporary_asset_id:
        temporaryAssetId,

      source_labels:
        sourceLabels,

      constraints:
        providerConstraints,

      // Keep original constraints for traceability.
      source_constraints:
        rawConstraints
    },

    temporary_asset_id:
      temporaryAssetId,

    source_labels:
      sourceLabels,

    // Node 07A uses these provider-safe constraints
    // when constructing the Runway prompt.

    constraints:
      providerConstraints,

    provider_route_supported:
      supported,

    provider_route:
      supported
        ? "VISUAL_IMAGE_GENERATION"
        : "UNSUPPORTED_ASSET_TYPE",

    job_status:
      supported
        ? "READY_FOR_PROVIDER_ROUTING"
        : "UNSUPPORTED_ASSET_TYPE",

    // This is supplied by Node 05A.
    attempt_number:
      resolvedAttemptNumber
  }
};

