      `${index + 1}. ${constraint}`
  ),

  `Do not redesign Mikko or Lumi.`,
  `Do not add text, logos, captions, labels, borders, or watermarks.`,
  `Do not generate a mockup, presentation board, product card, frame, or decorative backdrop.`,
  `Keep the asset clearly separated from the canvas edges.`,
  `Produce one clean reusable asset suitable for preschool production and downstream compositing.`
].join("\n");

// ----------------------------------------------------
// FINAL PROVIDER REQUEST
// ----------------------------------------------------

return {
