    "SAFETY STOP: Polling context contains an invalid attempt_number."
  );
}

// ----------------------------------------------------
// DETERMINE HOW WE ARRIVED HERE
// ----------------------------------------------------

const resumed =
  job.resume_existing_provider_task === true ||
  job.resumed_provider_task === true;

// ----------------------------------------------------
// RETURN NORMALIZED POLLING CONTEXT
// ----------------------------------------------------

return {
  json: {
    ...job,

    provider:
      "RUNWAY",

    provider_job_id:
      providerJobId,

    resumed_provider_task:
      resumed,

    polling_context_source:
      resumed
        ? "EXISTING_PROVIDER_TASK"
        : "NEW_SUBMISSION_CHECKPOINT",

    job_status:
      "PROVIDER_JOB_SUBMITTED"
  }
};

