      reservation_id: reservationId,

      reservation_created: true,

      submission_authorized: true,

      reservation_job_status: "SUBMISSION_RESERVED",

      job_status: "SUBMISSION_RESERVED"
    },

    pairedItem: {
      item: 0
    }
  }
];

// AGENT-007 — NODE 07A6
// Verify Runway Dispatch Claim
//
// Verifies that Supabase atomically claimed the exact
// reservation before any paid Runway submission.
//
// No API calls or database writes occur here.

const inputs = $input.all();

if (inputs.length !== 1) {
  throw new Error(
    `SAFETY STOP: Expected one dispatch claim response, received ${inputs.length}.`
  );
}

const claim = inputs[0].json;

// ------------------------------------------------------------
// 01 — RECOVER THE MATCHING RESERVATION CONTEXT
// ------------------------------------------------------------

let request;

try {
  request =
    $('07A4 - Verify Generation Reservation')
      .itemMatching(0)
      .json;
} catch (error) {
  throw new Error(
    "SAFETY STOP: Cannot match dispatch claim to " +
    "its original reservation. " +
    error.message
  );
}

// ------------------------------------------------------------
// 02 — VERIFY RESERVATION AUTHORISATION
// ------------------------------------------------------------

if (
  request.reservation_created !== true ||
  request.submission_authorized !== true ||
  request.reservation_job_status !== "SUBMISSION_RESERVED"
) {
  throw new Error(
    "SAFETY STOP: Original reservation is not authorised."
  );
}

// ------------------------------------------------------------
// 03 — VERIFY CLAIM RESULT
// ------------------------------------------------------------

if (
  claim.dispatch_claimed !== true ||
  claim.job_status !== "SUBMISSION_DISPATCH_CLAIMED"
) {
  throw new Error(
    "SAFETY STOP: Supabase did not grant the dispatch claim."
  );
}

// ------------------------------------------------------------
// 04 — VERIFY RESERVATION ID
// ------------------------------------------------------------

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (
  typeof request.reservation_id !== "string" ||
  !uuidPattern.test(request.reservation_id) ||
  claim.reservation_id !== request.reservation_id
) {
  throw new Error(
    "SAFETY STOP: Dispatch claim reservation ID mismatch."
  );
}

// ------------------------------------------------------------
// 05 — VERIFY EXACT ASSET IDENTITY
// ------------------------------------------------------------

const identityFields = [
  "asset_creation_batch_id",
  "production_readiness_manifest_id",
  "requirement_key",
  "source_asset_id"
];

for (const field of identityFields) {

  if (
    !request[field] ||
    claim[field] !== request[field]
  ) {
    throw new Error(
      `SAFETY STOP: Dispatch identity mismatch: ${field}.`
    );
  }

}

// ------------------------------------------------------------
// 06 — VERIFY ATTEMPT NUMBER
// ------------------------------------------------------------

const attemptNumber =
  Number(request.attempt_number);

if (
  attemptNumber !== 1 ||
  Number(claim.attempt_number) !== attemptNumber
) {
  throw new Error(
    "SAFETY STOP: Invalid dispatch attempt. Version 0.1 permits attempt 1 only."
  );
}

// ------------------------------------------------------------
// 07 — BLOCK EXISTING PROVIDER TASKS
// ------------------------------------------------------------

if (
  request.resume_existing_provider_task === true ||
  request.resumed_provider_task === true ||
  request.resume_provider_job_id ||
  request.provider_job_id
) {
  throw new Error(
    "SAFETY STOP: Existing provider task entered new dispatch path."
  );
}

// ------------------------------------------------------------
// 08 — VERIFY GENERATION REQUEST
// ------------------------------------------------------------

if (
  typeof request.generation_prompt !== "string" ||
  !request.generation_prompt.trim()
) {
  throw new Error(
    "SAFETY STOP: Generation prompt is missing."
  );
}

// ------------------------------------------------------------
// 09 — RETURN VERIFIED DISPATCH CONTEXT
// ------------------------------------------------------------

return [
  {
    json: {
      ...request,

      reservation_id:
        request.reservation_id,

      reservation_created:
        true,

      submission_authorized:
        true,

      dispatch_claimed:
        true,

      dispatch_claim_status:
        "SUBMISSION_DISPATCH_CLAIMED",

      job_status:
        "SUBMISSION_DISPATCH_CLAIMED"
    },

    pairedItem: {
      item: 0
    }
  }
];

// AGENT-007 — Reporting input only.
// No provider calls or database writes.

return [
  {
    json: {
      asset_creation_batch_id: "A007-1789527180412",
      production_readiness_manifest_id:
        "d124ba28-2dc5-4b86-8608-f363eeb3f8d2",
      remaining_job_count: 0,
      test_only: true
    }
  }
];
